function symmetryShare(ctx) {
  const places = ctx.places, n = ctx.n;
  if (!n) return 0;
  const CELL = 4;
  const grid = new Map();
  const key = (x, y, z) => x + ',' + y + ',' + z;
  for (let i = 0; i < n; i++) {
    const p = places[i];
    const k = key(Math.floor(p.pos[0]/CELL), Math.floor(p.pos[1]/CELL), Math.floor(p.pos[2]/CELL));
