    if (!Number.isFinite(c)) continue;
    let hit = 0;
    for (let i = 0; i < n; i++) {
      const p = places[i];
      const tx = 2 * c - p.pos[0], ty = p.pos[1], tz = p.pos[2];
      const twin = chiralityTwin(p.part);
